package app.xenet.client;
import org.json.*;import java.util.*;
/** Immutable, bounded per-connection settings. Missing settings preserve provider behavior. */
public final class ConnectionOptions {
 public final String mux,fragment,dns,appMode,fragmentSize,fragmentDelay,keepAlive;public final int concurrency,mtu,retryCount,retryDelay,pingTimeout;public final boolean reconnect;public final Set<String> packages;
 public ConnectionOptions(JSONObject v)throws Exception {JSONObject o=v==null?new JSONObject():v;for(String key:new String[]{"concurrency","mtu","retryCount","retryDelay","pingTimeout"})if(o.has(key)&&(!(o.opt(key) instanceof Number)||((Number)o.get(key)).doubleValue()!=((Number)o.get(key)).intValue()))throw new IllegalArgumentException("BAD_OPTIONS");mux=o.optString("mux","config");fragment=o.optString("fragment","config");dns=o.optString("dns","1.1.1.1");appMode=o.optString("appMode","all");concurrency=o.optInt("concurrency",4);mtu=o.optInt("mtu",1400);reconnect=o.optBoolean("reconnect",true);fragmentSize=o.optString("fragmentSize","100-200");fragmentDelay=o.optString("fragmentDelay","10-20");keepAlive=o.optString("keepAlive","config");retryCount=o.optInt("retryCount",3);retryDelay=o.optInt("retryDelay",1000);pingTimeout=o.optInt("pingTimeout",2000);if(!Arrays.asList("50-100","100-200","200-400").contains(fragmentSize)||!Arrays.asList("0-1","1-3","10-20").contains(fragmentDelay)||!Arrays.asList("config","on").contains(keepAlive)||!Arrays.asList(1,3,5).contains(retryCount)||!Arrays.asList(1000,2000,5000).contains(retryDelay)||!Arrays.asList(2000,4000,6000).contains(pingTimeout))throw new IllegalArgumentException("BAD_OPTIONS");if(!Arrays.asList("config","off","on").contains(mux)||!Arrays.asList("config","tlshello").contains(fragment)||!Arrays.asList("1.1.1.1","8.8.8.8","9.9.9.9").contains(dns)||!Arrays.asList("all","include","exclude").contains(appMode)||concurrency<1||concurrency>16||mtu<1280||mtu>1500)throw new IllegalArgumentException("BAD_OPTIONS");Set<String> p=new TreeSet<>();JSONArray a=o.optJSONArray("packages");if(a!=null){if(a.length()>500)throw new IllegalArgumentException("BAD_OPTIONS");for(int i=0;i<a.length();i++){String n=a.getString(i);if(n.length()>255||!n.matches("[A-Za-z0-9_]+(?:\\.[A-Za-z0-9_]+)+"))throw new IllegalArgumentException("BAD_OPTIONS");p.add(n);}}packages=Collections.unmodifiableSet(p);}
 public JSONObject json()throws Exception{return Parser.obj("mux",mux,"fragment",fragment,"dns",dns,"appMode",appMode,"concurrency",concurrency,"mtu",mtu,"reconnect",reconnect,"packages",new JSONArray(packages),"fragmentSize",fragmentSize,"fragmentDelay",fragmentDelay,"keepAlive",keepAlive,"retryCount",retryCount,"retryDelay",retryDelay,"pingTimeout",pingTimeout);}
 public static ConnectionOptions defaults()throws Exception{return new ConnectionOptions(null);}
 public static boolean muxCompatible(JSONObject proxy){String p=proxy.optString("protocol");JSONObject stream=proxy.optJSONObject("streamSettings");String net=stream==null?"tcp":stream.optString("network","tcp");if(!Arrays.asList("vmess","vless","trojan").contains(p)||!Arrays.asList("tcp","raw","ws").contains(net))return false;return !proxy.toString().contains("xtls-rprx");}
 public static boolean fragmentCompatible(JSONObject proxy){JSONObject stream=proxy.optJSONObject("streamSettings");if(stream==null||!stream.optString("security").equals("tls"))return false;String n=stream.optString("network","tcp");JSONObject sock=stream.optJSONObject("sockopt"),chain=proxy.optJSONObject("proxySettings");return Arrays.asList("tcp","raw","ws").contains(n)&&(sock==null||sock.optString("dialerProxy").isEmpty())&&(chain==null||chain.optString("tag").isEmpty());}
 public static boolean tcpCompatible(JSONObject p){if(p.optString("protocol").equals("wireguard"))return false;JSONObject stream=p.optJSONObject("streamSettings");return stream==null||Arrays.asList("tcp","raw","ws","grpc","httpupgrade","xhttp","splithttp","h2","http").contains(stream.optString("network","tcp"));}
 public static JSONObject merge(JSONObject current,JSONObject patch)throws Exception{JSONObject updated=new ConnectionOptions(current).json();Iterator<String> keys=patch.keys();while(keys.hasNext()){String key=keys.next();updated.put(key,patch.get(key));}return new ConnectionOptions(updated).json();}
 /** Copy only; never modify imported config JSON. Existing provider chains are preserved. */
 public JSONArray apply(JSONArray original)throws Exception{JSONArray a=new JSONArray(original.toString());JSONObject p=a.getJSONObject(0);if(mux.equals("off"))p.put("mux",Parser.obj("enabled",false));else if(mux.equals("on")&&muxCompatible(p))p.put("mux",Parser.obj("enabled",true,"concurrency",concurrency,"xudpConcurrency",-1));
  if(fragment.equals("tlshello")&&fragmentCompatible(p)){String tag="xenet-fragment";Set<String> tags=new HashSet<>();for(int i=0;i<a.length();i++)tags.add(a.getJSONObject(i).optString("tag"));while(tags.contains(tag))tag+="-1";JSONObject stream=p.getJSONObject("streamSettings"),sock=stream.optJSONObject("sockopt");if(sock==null){sock=new JSONObject();stream.put("sockopt",sock);}sock.put("dialerProxy",tag);a.put(Parser.obj("tag",tag,"protocol","freedom","settings",Parser.obj("fragment",Parser.obj("packets","tlshello","length",fragmentSize,"interval",fragmentDelay))));}if(keepAlive.equals("on")&&tcpCompatible(p)){JSONObject stream=p.optJSONObject("streamSettings");if(stream==null){stream=new JSONObject();p.put("streamSettings",stream);}JSONObject sock=stream.optJSONObject("sockopt");if(sock==null){sock=new JSONObject();stream.put("sockopt",sock);}sock.put("tcpKeepAliveIdle",45).put("tcpKeepAliveInterval",15);}return a;}
}
